input.sparql:
SELECT ?point ?ts WHERE {
  ?point a brick:ElectricityMeter ;
         brick:hasParent [a brick:Building] .
  ?point ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?ts .
}

SELECT ?point ?class ?ts WHERE {
  ?point a ?class .
  FILTER (str(?class) LIKE '%Electric%')
  ?point ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?ts .
}
